def can_partition(S, k):
    import itertools
    n = len(S)
    for i in range(1 << n):
        s1 = 0
        for j in range(n):
            if (i >> j) & 1:
                s1 += S[j]
        if s1 <= 1 and (k - s1) <= 6:
            return True
    return False

def find_counterexample(k, max_n=15):
    import random
    for _ in range(10000):
        n = random.randint(1, max_n)
        # Generate a set S with sum k and each element in (0, 1]
        # This is a bit tricky, let's try a simpler way.
        # Generate n-1 random numbers in (0, 1], then the last one is k - sum.
        # If the last one is not in (0, 1], restart.
        S = [random.random() for _ in range(n-1)]
        last = k - sum(S)
        if 0 < last <= 1:
            S.append(last)
            if not can_partition(S, k):
                return S
    return None

for k in [6.5, 6.51, 6.6]:
    print(f"k={k}: {find_counterexample(k)}")
